const rebuildClosureForMovedSubtree = `-- name: RebuildClosureForMovedSubtree :exec
INSERT INTO workspace_closure (ancestor_id, descendant_id, depth)
SELECT 
    new_ancestors.ancestor_id, 
    subtree_nodes.descendant_id, 
    new_ancestors.depth + subtree_nodes.depth + 1
FROM workspace_closure AS new_ancestors
CROSS JOIN workspace_closure AS subtree_nodes
WHERE new_ancestors.descendant_id = $2
  AND subtree_nodes.ancestor_id = $1
`

type RebuildClosureForMovedSubtreeParams struct {
	AncestorID   uuid.UUID `json:"ancestor_id"`
	DescendantID uuid.UUID `json:"descendant_id"`
}

// Connect new ancestors to all nodes in the moved subtree
func (q *Queries) RebuildClosureForMovedSubtree(ctx context.Context, arg RebuildClosureForMovedSubtreeParams) error {
	_, err := q.db.Exec(ctx, rebuildClosureForMovedSubtree, arg.AncestorID, arg.DescendantID)
	return err
}

